var view=UnityEngine.Object.FindFirstObjectByType<PokeChess.Client.UI.PlacementSandboxView>();
var checks=new System.Collections.Generic.List<object>();
foreach(int count in new[]{4,6,8})
{
    view.ResetPairingDemo(count);
    for(int round=1;round<=3;round++)
    {
        if(view.Match.RoundNumber!=round || view.RoundTimerText.Contains("VS") || view.DetailText.Contains("vs"))throw new System.Exception("Preparation failed");
        var plan=view.Match.PairingPlan;
        if(plan.PreviousRoundRematches!=0 || plan.TwoRoundsAgoRematches!=0)throw new System.Exception("Recent opponent not avoided");
        view.AdvanceRoundTime(30);
        if(view.Match.Phase!=PokeChess.Core.Match.MatchPhase.Combat || view.RoundLoop.Battles.Count!=count/2)throw new System.Exception("Combat failed");
        int frames=0;
        while(view.Match.Phase==PokeChess.Core.Match.MatchPhase.Combat && frames++<1400)view.AdvanceRoundTime(1d/30);
        if(!view.RoundLoop.IsSettled || view.RoundLoop.LastResult.XP.Count!=count || !view.RoundResultText.Contains("VS"))throw new System.Exception("Settlement failed");
        checks.Add(new {players=count,round,frames,opponent=view.RoundLoop.GetBattleFor("p1").Pairing.OpponentOf("p1"),payouts=view.RoundLoop.LastResult.Income.Count});
        view.AdvanceRoundTime(3);
        if(view.Match.Phase!=PokeChess.Core.Match.MatchPhase.Preparation || view.Match.RoundNumber!=round+1)throw new System.Exception("Next preparation failed");
    }
}
